const slaves  = [1, 2, 3];
const delayMs = 1200;

slaves.forEach((id, idx) => {
    setTimeout(() => {
        node.send({
            topic:   'slave' + id,
            slaveId: id,
            payload: {
                value:    0,
                unitid:   id,
                fc:       3,
                address:  0,
                quantity: 27    // 27 registros: 7xPZEM-A + 7xPZEM-B + 13 sistema
            }
        });
    }, idx * delayMs);
});

return null;

const r = msg.payload;
const d = Array.isArray(r) ? r
        : (r && Array.isArray(r.data)) ? r.data
        : null;

const id = parseInt(String(msg.topic).replace('slave','')) || msg.slaveId || 0;

if (!d || d.length < 27) {
    node.warn('Slave ' + id + ' regs=' + (d ? d.length : 0) + ' (esperados 27)');
    return null;
}

function u32(hi, lo) { return ((hi << 16) | lo) >>> 0; }
function signed(v)   { return v > 32767 ? v - 65536 : v; }

// Sistema (registros 14-26)
const ip      = d[14]+'.'+d[15]+'.'+d[16]+'.'+d[17];
const rssi    = signed(d[18]);
const heap    = u32(d[19], d[20]);
const uptime  = u32(d[21], d[22]);
const temp_c  = +(d[23] / 10).toFixed(1);
const slave_id = d[24] || id;
const fw_ver  = (d[25] / 100).toFixed(1);
const wifi_ok = d[26] === 1 ? 1 : 0;
const ts      = new Date().toISOString();

// PZEM A (registros 0-6)
const whA = u32(d[3], d[4]);
const meterA = {
    slave_id, meter: 1,
    voltage:    +(d[0] / 10).toFixed(1),
    current:    +(d[1] / 100).toFixed(2),
    power_w:     d[2],
    energy_wh:   whA,
    energy_kwh: +(whA / 1000).toFixed(3),
    frequency:  +(d[5] / 10).toFixed(1),
    pf:         +(d[6] / 100).toFixed(2),
    ip, rssi_dbm: rssi, free_heap: heap,
    uptime_s: uptime, temp_c, fw_ver, wifi_ok, ts
};

// PZEM B (registros 7-13)
const whB = u32(d[10], d[11]);
const meterB = {
    slave_id, meter: 2,
    voltage:    +(d[7]  / 10).toFixed(1),
    current:    +(d[8]  / 100).toFixed(2),
    power_w:     d[9],
    energy_wh:   whB,
    energy_kwh: +(whB / 1000).toFixed(3),
    frequency:  +(d[12] / 10).toFixed(1),
    pf:         +(d[13] / 100).toFixed(2),
    ip, rssi_dbm: rssi, free_heap: heap,
    uptime_s: uptime, temp_c, fw_ver, wifi_ok, ts
};

// Envía 2 mensajes separados (uno por medidor)
node.send({ ...msg, topic: 'modbus/slave/' + slave_id + '/meter/1', payload: meterA });
node.send({ ...msg, topic: 'modbus/slave/' + slave_id + '/meter/2', payload: meterB });
return null;

const d = msg.payload;
const sid = String(d.slave_id || 0);
const mid = String(d.meter || 0);

// Formato array [[fields, tags]] — compatible con todas las versiones
// Tags: slave_id (ESP32) + meter (1=PZEM-A, 2=PZEM-B)
msg.payload = [[
    {
        voltage    : d.voltage,
        current    : d.current,
        power_w    : parseInt(d.power_w),
        energy_kwh : d.energy_kwh,
        frequency  : d.frequency,
        pf         : d.pf,
        rssi_dbm   : parseInt(d.rssi_dbm),
        free_heap  : parseInt(d.free_heap),
        uptime_s   : parseInt(d.uptime_s),
        temp_c     : d.temp_c,
        wifi_ok    : parseInt(d.wifi_ok)
    },
    {
        slave_id : sid,
        meter    : mid,
        ip       : d.ip,
        fw_ver   : d.fw_ver
    }
]];

return msg;
